import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import env from '@next/env';import {getPgPool} from '../server/database/pgClient.js';
env.loadEnvConfig(process.cwd());const folder=path.join(process.env.USERPROFILE,'Downloads/updates/revision-gastos-20261004'),before=JSON.parse(fs.readFileSync(path.join(folder,'before.json'),'utf8')),pool=getPgPool(),db=await pool.connect(),cents=v=>Math.round(Number(v)*100);
try{
 await db.query('BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY');const after={};for(const t of Object.keys(before))after[t]=JSON.parse(JSON.stringify((await db.query('SELECT * FROM '+t)).rows));
 assert.equal(after.tesoreria_movimientos_bancarios.length,before.tesoreria_movimientos_bancarios.length);
 for(const m of before.tesoreria_movimientos_bancarios){const a=after.tesoreria_movimientos_bancarios.find(a=>a.id_linea_banco===m.id_linea_banco);for(const k of ['importe','fecha_valor','fecha_operativa','concepto','banco'])assert.deepEqual(a[k],m[k]);if(Number(m.importe)>0)assert.deepEqual(a,m);}
 assert.deepEqual(after.tesoreria_cargos_recurrentes,before.tesoreria_cargos_recurrentes);
 for(const a of before.laboral_anticipos)assert.deepEqual(after.laboral_anticipos.find(r=>r.id===a.id),a);
 const payrollPlan=JSON.parse(fs.readFileSync(path.join(folder,'payroll-plan.json'),'utf8'));
 for(const g of payrollPlan.plans.filter(g=>g.decisions.length)){const n=after.laboral_nominas.find(n=>n.id_empleado===g.employee&&n.anio===g.year&&n.mes===g.month);assert(n);assert.equal(n.estado,'pagado');assert.equal(cents(n.importe_neto),cents(g.expected));const final=after.tesoreria_movimientos_bancarios.find(m=>m.id_linea_banco===n.id_transferencia),advances=after.laboral_anticipos.filter(a=>a.id_empleado===g.employee&&a.anio===g.year&&a.mes===g.month&&a.estado==='pagado');assert.equal(cents(n.importe_neto),cents(Math.abs(final.importe))+advances.reduce((s,a)=>s+cents(a.importe_neto),0));}
 const expensePlan=JSON.parse(fs.readFileSync(path.join(folder,'expense-plan.json'),'utf8'));
 for(const p of expensePlan.plans.concat(expensePlan.confirmed)){const m=after.tesoreria_movimientos_bancarios.find(m=>m.id_linea_banco===p.id);assert.equal(m.estado_revision,true);assert.equal(String(m.id_cargo_recurrente),p.charge);assert.equal(m.id_proveedor,p.provider);}
 const paidIds=after.laboral_nominas.map(n=>n.id_transferencia).filter(Boolean),advanceIds=after.laboral_anticipos.map(a=>a.id_transferencia).filter(Boolean);assert.equal(new Set(paidIds).size,paidIds.length);assert.equal(new Set(advanceIds).size,advanceIds.length);assert(!paidIds.some(id=>advanceIds.includes(id)));
 const result={verified:true,bankLines:after.tesoreria_movimientos_bancarios.length,negativeLines:after.tesoreria_movimientos_bancarios.filter(m=>Number(m.importe)<0).length,confirmedPayrollMonths:payrollPlan.plans.filter(g=>g.decisions.length).length,payrollChanges:JSON.parse(fs.readFileSync(path.join(folder,'applied-payroll.json'),'utf8')).reduce((s,g)=>s+(g.ids?.length||0),0),newMonthlyPayrolls:after.laboral_nominas.length-before.laboral_nominas.length,newAdvances:after.laboral_anticipos.length-before.laboral_anticipos.length,expenseChanges:expensePlan.plans.length,alreadyCorrectExpenses:expensePlan.confirmed.length,unresolvedExpenseLines:expensePlan.held.length,dueApplications:after.tesoreria_vencimientos_aplicaciones.length,unchangedIncomeAndRecurringForecasts:true};
 fs.writeFileSync(path.join(folder,'after.json'),JSON.stringify(after));fs.writeFileSync(path.join(folder,'verified-result.json'),JSON.stringify(result,null,2));await db.query('ROLLBACK');console.log(JSON.stringify(result));
}finally{db.release();await pool.end();}

